css:
.row {
  display: flex;
  gap: 12px;
  padding: 12px;
}

.card {
  flex: 1;
  display: flex;
  flex-direction: column;
  padding: 16px;
  background: #fed7aa;
  border: 1px solid #f97316;
  border-radius: 6px;
}

.title,
.text,
.price {
  margin: 0;
}

.title {
  font-weight: 600;
}

.text {
  margin-top: 8px;
}

.price {
  margin-top: auto; /* push to the bottom */
  padding-top: 12px;
  font-weight: 700;
}
